// Oeste Footer — Huntington theme (v0.2.0).
// Copy-paste ready. Requires: React 18+, Tailwind with arbitrary values, JSX transform.
// Requires Huntington tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/huntington/src/index.js
// Docs: https://oeste.hiddeninwest.com/huntington/#/components/footer

export function Footer({ children }) {
  return (
    <footer className="pt-20">
      <p className="m-0 max-w-[544px] text-[var(--type-footer-size)] leading-[var(--type-footer-leading)] text-[var(--color-muted)] [font-weight:var(--type-footer-weight)]">{children || "\u00a9 2026 Brand name \u00b7 Footer copy goes here."}</p>
    </footer>
  );
}
